// ─── File: components/NavBar.ts ───
// Component object for the shared header — reused by MANY pages,
// so the locators live here ONCE instead of being duplicated.
import { Page, Locator } from '@playwright/test';

export class NavBar {
  readonly logout: Locator;
  readonly balance: Locator;
  constructor(page: Page) {
    this.logout = page.getByRole('button', { name: 'Logout' });
    this.balance = page.getByTestId('nav-balance');
  }
  async readBalance(): Promise<string> { return (await this.balance.innerText()).trim(); }
  async logoutUser() { await this.logout.click(); }
}
