// ─── File: pages/TransferPage.ts ───
// Page object: locators + intention-revealing methods. Composes NavBar
// so it stays focused (not a 1000-line god class).
import { Page, Locator } from '@playwright/test';
import { NavBar } from '../components/NavBar';

export class TransferPage {
  readonly nav: NavBar;                 // composition, not duplication
  private readonly from: Locator;
  private readonly to: Locator;
  private readonly amount: Locator;
  private readonly submit: Locator;

  constructor(private page: Page) {
    this.nav = new NavBar(page);
    this.from = page.getByLabel('From account');
    this.to = page.getByLabel('To account');
    this.amount = page.getByLabel('Amount');
    this.submit = page.getByRole('button', { name: 'Transfer' });
  }

  async goto() { await this.page.goto('/transfer'); }

  // One meaningful action reused by many tests.
  async makeTransfer(from: string, to: string, amount: string) {
    await this.from.selectOption(from);
    await this.to.fill(to);
    await this.amount.fill(amount);
    await this.submit.click();
  }
  // NOTE: business assertions stay in the SPEC, not here, so this page
  // object is reusable by tests expecting success OR failure.
}
