// THIN spec: expresses intent, calls page methods, asserts outcomes.
import { test, expect } from '../fixtures/fixtures';

test('transfer reduces the source balance', async ({ transferPage }) => {
  await transferPage.makeTransfer('SAV2001', 'CUR3001', '50000');

  // Business assertion lives HERE, using the reused NavBar component.
  await expect(transferPage.nav.balance).toContainText('950,000');
});

test('transfer appears regardless of expected outcome (reuse)', async ({ transferPage }) => {
  await transferPage.makeTransfer('SAV2001', 'CUR3001', '1');
  await expect(transferPage.nav.balance).toContainText('999,999');
});
